INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71327, 'spa', 'Mudo, incapaz de hablar', 'Mudo, incapaz de hablar. Describe a una persona que no puede hablar, ya sea por opresión demoníaca o por aflicción física. En Mateo 9:32-33 un endemoniado mudo es traído a Jesús y habla después de que el demonio es expulsado; en Mateo 12:22 un hombre ciego y mudo es sanado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71328, 'spa', 'Sordo, incapaz de oír', 'Sordo, incapaz de oír. Describe a una persona que no puede oír. En Mateo 11:5 y Lucas 7:22, Jesús cita la profecía mesiánica de Isaías de que ''los sordos oyen'' como evidencia de su identidad. Marcos 7:32 presenta a un hombre sordo y con impedimento del habla, sanado por Jesús con la orden aramea ''Efatá.''');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71331, 'spa', 'Obtener por suerte', 'Obtener por suerte, recibir por asignación divina o reparto providencial. Abarca tanto el sorteo literal como el sentido figurado de recibir algo como porción divinamente asignada. En Lc 1:9 el sorteo asigna a Zacarías su turno sacerdotal; en Jn 19:24 los soldados echan suertes por la túnica de Jesús, cumpliendo el Sal 22:18. En Hch 1:17 y 2 Pe 1:1 el término designa una participación otorgada por Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71332, 'spa', 'Lázaro (nombre propio)', 'Lázaro (nombre propio). Nombre propio que designa a dos figuras del Nuevo Testamento. Lázaro de Betania es el hombre que Jesús resucitó de la muerte después de cuatro días (Jn 11:1-44; 12:1-2, 9-10, 17), un acontecimiento que cristaliza tanto la fe como la oposición. El Lázaro de la parábola es el hombre pobre que yacía a la puerta del rico cubierto de llagas (Lc 16:20-25), cuyo consuelo posterior a la muerte ilustra la inversión divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71333, 'spa', 'En secreto', 'En secreto, a escondidas, sin conocimiento público. Describe una acción realizada en privado para evitar ser descubierto o llamar la atención. Los cuatro usos neotestamentarios abarcan diversas motivaciones: la discreción misericordiosa de José hacia María (Mt 1:19), la maquinación secreta de Herodes con los magos (Mt 2:7), la llamada discreta de Marta a María junto a la tumba de Lázaro (Jn 11:28), y el intento de los magistrados de liberar a Pablo sin dar explicaciones (Hch 16:37).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71334, 'spa', 'Tempestad violenta', 'Tempestad violenta, torbellino o vendaval furioso. Marcos 4:37 y Lucas 8:23 emplean este término en los relatos paralelos de la tormenta en el mar de Galilea: se levantó un gran temporal, las olas golpeaban la barca y esta comenzó a llenarse de agua mientras Jesús dormía. Al calmar el viento y el mar, demostró autoridad divina sobre el caos. 2 Pedro 2:17 lo usa metafóricamente para describir a los falsos maestros.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71336, 'spa', 'hablar, decir', 'Hablar, decir, contar en voz activa: comunicación verbal general que abarca todas las personas, tiempos y modos de λαλέω (277 apariciones). El español hablar y el alemán reden se alinean estrechamente con este verbo de comunicación no marcado. Cubre tanto la conversación ordinaria como el discurso divino autoritativo: el endemoniado mudo «habló» al ser sanado (Mt 9:33), Jesús «habló» a las multitudes en parábolas (Mt 13:34).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71351, 'spa', 'ser hablado, ser dicho', 'Formas de voz pasiva y medio-pasiva que significan «ser hablado», «ser dicho» o «ser anunciado» (22 apariciones). El cambio a la pasiva reorienta la comunicación desde la acción del hablante hacia el contenido transmitido o la recepción del oyente. Pasajes clave incluyen Lc 1:45, donde Elisabet bendice a María porque «se cumplirán las cosas que le fueron dichas de parte del Señor», y Mr 14:9.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71404, 'spa', 'Habla o dialecto', 'Habla, modo de hablar, dialecto o acento. Engloba tanto el acto de hablar como la manera distintiva que identifica al hablante. En Mt 26:73 y Mr 14:70, la λαλιά de Pedro —su acento galileo— lo delata durante el juicio de Jesús. En Jn 4:42 los samaritanos dicen que ya no creen por la λαλιά de la mujer sino por haberlo oído ellos mismos. En Jn 8:43 Jesús contrasta su λαλιά con su λόγος.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71406, 'spa', 'tomar, coger', 'Tomar o coger activamente algo con las manos: 113 apariciones, especialmente prominentes en secuencias narrativas de acción. La forma participial «habiendo tomado» (λαβών) es casi formularia antes de bendecir y partir el pan (Mt 14:19; 15:36; 26:26). Aquí el agente ejerce la iniciativa: tomar una copa, recoger un rollo, reunir provisiones. El español tomar refleja fielmente este sentido volitivo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71408, 'spa', 'recibir, obtener', 'Recibir u obtener algo dado, ofrecido o debido: el grupo semántico más amplio con 134 apariciones. Abarca recibir dones (Mt 10:8), salario (Jn 4:36), el Espíritu (Jn 20:22), autoridad (Ap 2:27), promesas y herencia. El énfasis recae sobre el receptor como beneficiario más que como agente activo. El español recibir capta con precisión este marco de recepción pasiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71432, 'spa', 'acoger, recibir a alguien', 'Aceptar o acoger a una persona, especialmente en contextos de hospitalidad o reconocimiento de autoridad. En Jn 5:43 Jesús dice «no me recibís»; en 2 Jn 1:10 se advierte a los creyentes que no «reciban» en sus casas a falsos maestros. El español recibir a (una persona) y acoger distinguen esta recepción interpersonal de la recepción de objetos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71441, 'spa', 'asir, prender', 'Asir, atrapar o prender por la fuerza: acepción nítidamente distinta con 6 apariciones. En Lc 5:5 Pedro no «atrapó» nada en toda la noche; en Lc 5:26 el asombro «se apoderó» de la multitud; en 1 Co 10:13 la tentación «sorprende» a los creyentes. El coreano 잡다 y el suajili -shika seleccionan vocabulario de prensión forzada, confirmando que el elemento violento o involuntario es translingüísticamente relevante.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71461, 'spa', 'ser tomado, ser recibido', 'Formas de voz pasiva donde el sujeto es tomado o recibido: solo 2 apariciones claras (1 Ti 4:4; He 5:1). En 1 Ti 4:4 el alimento es «recibido» con acción de gracias; en He 5:1 el sumo sacerdote es «tomado de entre los hombres». La morfología pasiva griega es confirmada por los sufijos pasivos del suajili (-wa).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71482, 'spa', 'cobrar, recaudar', 'Una sola aparición en Mt 17:24 donde el sentido es «cobrar»: los recaudadores del impuesto del templo «cobrando» la didracma. El español cobrando y el inglés collecting apuntan a un matiz transaccional y fiscal que no queda cubierto por el genérico «recibir» ni «tomar». Representa una subacepción fiscal especializada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71495, 'spa', 'Patriarca antediluviano', 'Presente en Lucas 3:36, este nombre vincula la genealogía de Jesús con los antiguos patriarcas entre Adán y Noé. Las traducciones multilingües muestran un reconocimiento uniforme de este patriarca antediluviano, con transliteraciones que preservan el sonido gutural distintivo del original hebreo a través de las diversas tradiciones lingüísticas europeas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71496, 'spa', 'Lámpara de aceite', 'Lámpara de aceite portátil, un pequeño recipiente lleno de aceite con una mecha que requiere reposición periódica. Es central en la parábola de las diez vírgenes (Mt 25:1, 3, 4, 7, 8), donde las doncellas insensatas dejan que sus lámparas se agoten. El hindi «deepak» (दीपक) y el árabe «masabiih» (مَصَابِيحَ) denotan la lámpara de aceite doméstica familiar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71497, 'spa', 'Antorcha / tea', 'Una antorcha o tea de mayor tamaño, llevada al exterior para iluminación o como señal visual dramática. La partida que arrestó a Jesús en Getsemaní vino con «antorchas y linternas y armas» (Jn 18:3), donde el español «antorcha» distingue claramente este objeto de una lámpara pequeña. En Apocalipsis, los siete espíritus de Dios arden como «antorchas de fuego» ante el trono (Ap 4:5), y la gran estrella cae del cielo como una antorcha (Ap 8:10).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71500, 'spa', 'Brillante / resplandeciente', 'Que emite o refleja luz; visualmente luminoso, brillante o radiante. Se usa del visitante angélico de Cornelio con «vestidura resplandeciente» (Hch 10:30), del manto burlesco puesto sobre Jesús (Lc 23:11), del lino de los ejércitos celestiales «brillante y puro» (Ap 15:6; 19:8) y del río de la vida «brillante como el cristal» (Ap 22:1). El español emplea «brillante» y «resplandeciente» para captar esta luminosidad visible.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71501, 'spa', 'Espléndido / magnífico', 'Espléndido, magnífico o lujoso en calidad, enfatizando lo costoso, la grandeza o la impresión social más que la mera luminosidad. Santiago advierte contra la deferencia hacia quien viste «ropa espléndida» mientras se desprecia al pobre (Stg 2:2-3), y Apocalipsis 18:14 enumera «cosas espléndidas» entre los lujos perdidos de Babilonia. El cambio del inglés de «bright» a «splendid/fine» señala que el énfasis ha pasado de la luz a la opulencia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71503, 'spa', 'Fulgor sobrenatural', 'Pablo emplea este vocablo en Hechos 26:13 para expresar que la luz celestial superaba incluso el resplandor del sol al mediodía, el punto de referencia natural más brillante disponible. Las traducciones multilingües (brightness, resplandor, splendeur) coinciden en destacar la intensidad luminosa, reflejando tanto su uso clásico para fenómenos radiantes como su aplicación teológica a la manifestación divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71504, 'spa', 'Lujo ostentoso', 'La única aparición en el Nuevo Testamento (Lucas 16:19) contrasta el diario banquetear espléndido del hombre rico con la miseria de Lázaro a su puerta. La evidencia interlingüística (splendidly, espléndidamente, splendidement) capta de manera uniforme el sentido de exceso lujoso, resaltando las dimensiones morales de la desigualdad que Jesús aborda en la parábola.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71505, 'spa', 'Brillar, dar luz', 'Emitir luz, resplandecer o brillar de forma visible. Cada uso neotestamentario implica radiancia que irrumpe en la oscuridad. En la transfiguración (Mt 17:2), el rostro de Jesús ''brilló como el sol'', expresando esplendor sobrenatural. En el Sermón del Monte (Mt 5:15-16), el verbo pasa de la luz de una lámpara al resplandor metafórico de las buenas obras.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71511, 'spa', 'Pasar inadvertido, estar oculto', 'Pasar inadvertido, estar oculto o permanecer ignorante de algo: verbo que describe el estado de algo encubierto a la percepción o conciencia. La construcción idiomática griega coloca al sujeto ''oculto'' como sujeto gramatical con un participio suplementario que expresa la acción inadvertida. Jesús ''no pudo pasar inadvertido'' en Tiro (Mark 7:24), la mujer con la hemorragia se da cuenta de que ''no pasó inadvertida'' (Luke 8:47), y Pedro señala que a los burladores ''les pasa inadvertido'' el poder creador de Dios (2 Pet 3:5).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71517, 'spa', 'Tallado en roca', 'Aplicado al sepulcro de Jesús en Lucas 23:53, este término enfatiza que la tumba fue recién labrada en roca viva y nunca había sido utilizada. Las traducciones multilingües (cut-in-rock, tallada-en-roca, taillé-dans-le-roc) reflejan la precisión técnica del griego, destacando tanto el método de construcción como su condición de lugar de sepultura costoso y honroso, digno de la realeza.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71518, 'spa', 'pueblo, nación (comunidad)', 'Un cuerpo colectivo de personas unido por identidad étnica, política o pactual. En la Septuaginta y el Nuevo Testamento, λαός es el término característico para Israel como pueblo elegido de Dios, distinto de los ἔθνη (las naciones). Esta resonancia pactual impregna pasajes clave: «salvará a su pueblo de sus pecados» (Mt 1:21), «un pueblo para posesión suya» (Tit 2:14; eco de Dt 7:6). Lucas-Hechos lo extiende a la Iglesia como nuevo pueblo de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71525, 'spa', 'Laodicea (ciudad)', 'Nombre propio de la ciudad de Laodicea en el valle del Lico de Frigia, un próspero centro comercial y bancario en la Asia Menor romana. Pablo la menciona en relación con la correspondencia colosense, expresando preocupación pastoral por sus creyentes (Col 2:1; 4:13, 15-16) y haciendo referencia a una carta ''desde Laodicea'' (Col 4:16). En Apocalipsis es la última de las siete iglesias, célebremente reprendida por su tibieza espiritual (Rev 3:14-22).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71526, 'spa', 'Gentilicio de Laodicea', 'La referencia de Pablo en Colosenses 4:16 a la iglesia laodicena y a una carta que esta poseía evidencia las redes cristianas tempranas en el oeste de Asia Menor. La evidencia multilingüe preserva la designación geográfico-étnica con variación mínima, reconociendo a Laodicea como un centro significativo del cristianismo apostólico y la correspondencia eclesiástica primitiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71527, 'spa', 'Garganta como sepulcro', 'En Romanos 3:13, Pablo emplea este término dentro de una cadena de citas del Antiguo Testamento para retratar la pecaminosidad universal. La imagen de la garganta como sepulcro abierto sugiere un habla que esparce muerte y corrupción. Las traducciones multilingües (garganta, throat, gosier, Kehle) reflejan el sentido anatómico, aunque la fuerza metafórica depende de la imaginería antigua.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71528, 'spa', 'Ciudad portuaria cretense', 'Mencionada en Hechos 27:8 como punto de referencia geográfico durante el peligroso viaje marítimo de Pablo, Lasea marca el lugar donde la travesía se volvió cada vez más arriesgada por la proximidad del invierno. Las glosas multilingües conservan el nombre con leves variaciones ortográficas (Lasaia, Lasáia, Lasea), siguiendo las prácticas habituales para transcribir topónimos griegos poco documentados.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71529, 'spa', 'Reventar violentamente', 'Hechos 1:18 emplea este verbo gráfico para describir la muerte de Judas: al caer de cabeza, su cuerpo se reventó y sus entrañas se derramaron. La evidencia multilingüe (reventó, burst-open, éclater) capta la ruptura violenta y repentina que implica el griego. Este relato complementa la narración de Mateo, enfatizando el trágico desenlace de Judas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71531, 'spa', 'Culto o servicio sagrado', 'Servicio religioso o culto: el deber formal o sentido de adoracion rendido a Dios. El termino abarca tanto el ritual exterior como la devocion interior. En Heb 9:1 y 9:6 se refiere concretamente a los ritos leviticos del tabernaculo; en Ro 9:4 es uno de los privilegios del pacto de Israel. El uso transformador de Pablo en Ro 12:1 convierte la ofrenda de la vida entera en verdadero «culto racional».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71532, 'spa', 'La dimension devocional', 'La dimension devocional: rendir adoracion y culto a Dios por reverencia y amor. Jesus cita este sentido directamente en la narrativa de la tentacion (Mt. 4:10; Lc. 4:8), y Pablo lo usa para la esperada adoracion de Israel (Hch. 26:7). El espanol ''que sirve/sirven'' conserva el matiz de servicio, mientras que el frances ''adorer'' resalta la postura de adoracion. Abarca 12 de 21 ocurrencias.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71533, 'spa', 'La dimension ministerial', 'La dimension ministerial: llevar a cabo deberes sagrados continuos o servicio liturgico ante Dios. Ana servia a Dios ''con ayunos y oraciones noche y dia'' (Lc. 2:37); Pablo sirve a Dios ''en mi espiritu en el evangelio'' (Ro. 1:9; 2 Ti. 1:3). Aqui el enfasis recae en un ministerio fiel y sostenido, mas que en un acto singular de adoracion. El aleman ''dienen/dient'' captura bien este servicio constante y activo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71545, 'spa', 'Hortaliza de huerto', 'Planta cultivada en el huerto: hortaliza o hierba sembrada para alimento. En la parabola de la mostaza (Mt 13:32; Mr 4:32) la planta sobrepasa a todas las hortalizas, subrayando el crecimiento sorprendente del reino. Lc 11:42 menciona hierbas especificas (menta, ruda, hortalizas) como objeto del diezmo farisaico, mientras que Ro 14:2 contrasta al que solo come legumbres con el que come de todo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71546, 'spa', 'Legión militar y demoníaca', 'Unidad militar romana que contaba miles de soldados, empleada en el NT tanto literalmente (de ejércitos angélicos, Mt 26:53) como en sentido de nombre propio para un colectivo demoníaco (Mc 5:9, 15; Lc 8:30). La autodesignación del endemoniado como «Legión» comunica no solo pluralidad, sino fuerza organizada y aplastante.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71547, 'spa', 'decir/hablar discursivo', 'Expresar palabras o pensamientos mediante el habla, hacer una declaración o sostener un discurso — ''decir'', ''hablar''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71563, 'spa', 'contar/mandar directivo', 'Comunicar con intención directiva o imperativa, dar una orden, mandato o instrucción — ''contar'', ''mandar'', ''ordenar''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71569, 'spa', 'llamar/nombrar designativo', 'Dar nombre a algo o alguien, designar o identificar mediante un nombre o título — ''llamar'', ''nombrar''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71589, 'spa', 'Remanente por gracia', 'En Romanos 11:5, Pablo argumenta que, así como en los días de Elías Dios preservó siete mil fieles, en su época existe un remanente conforme a la elección de la gracia. Las glosas multilingües (remanente, remnant, reste, Rest) reflejan el sentido de una porción sobreviviente, conectando con la teología bíblica de los pocos preservados por propósito divino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71590, 'spa', 'Liso, allanado', 'Lucas 3:5 cita la profecía de Isaías de que los lugares ásperos se convertirán en caminos llanos, como parte de la transformación del paisaje que anuncia la llegada mesiánica. La evidencia multilingüe (lisos, smooth, uni, λείας) capta la cualidad física de uniformidad, aunque el contexto profético le confiere significado espiritual: el allanamiento de barreras para la visitación divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71591, 'spa', 'Carecer, faltar', 'Carecer, ser deficiente o quedarse corto de lo necesario, usado en el NT para identificar una carencia o deficiencia específica que requiere remedio. Jesús señala la única deficiencia que le queda al joven rico (Luke 18:22), Pablo diagnostica lo que aún falta en las iglesias cretenses (Titus 1:5), y Santiago invita a los creyentes que carezcan de sabiduría a pedirla a Dios con confianza (Jas 1:5).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71596, 'spa', 'Ministrar y servir', 'Ministrar, servir o realizar un servicio religioso. Hechos 13:2 describe a los líderes de la iglesia en Antioquía «ministrando al Señor y ayunando» cuando el Espíritu Santo habló, indicando adoración y oración corporativas. Romanos 15:27 lo emplea para el servicio material de los creyentes gentiles hacia los judíos, dado que han participado de sus bendiciones espirituales. Hebreos 10:11 describe a los sacerdotes «ministrando cada día».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71597, 'spa', 'Servicio litúrgico o ministerio', 'Servicio religioso o sacerdotal rendido a Dios o a la comunidad creyente. En Luke 1:23, Zacarías termina su leitourgia en el templo, reflejando la rotación sacerdotal levítica. Pablo extiende el término al ministerio apostólico y congregacional: en 2 Cor 9:12 la ofrenda económica de los corintios se llama leitourgia que suple las necesidades de los santos, mientras que en Phil 2:17 Pablo presenta su propio trabajo como ofrenda sacerdotal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71601, 'spa', 'Espíritus ministradores', 'Hebreos 1:14 aplica este término a los ángeles, definiéndolos como espíritus ministradores enviados al servicio de los creyentes. La evidencia multilingüe (ministering, servidores, dienend) subraya uniformemente la dimensión de servicio activo. Esto contrasta deliberadamente con la supremacía de Cristo en Hebreos 1: mientras los ángeles sirven, Cristo reina como Hijo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71602, 'spa', 'Ministro o servidor público', 'Ministro o servidor público que desempeña un servicio en nombre de otro, ya sea en contextos cívicos, personales o sagrados. Las raíces etimológicas en el deber público le confieren un peso de responsabilidad oficial. Pablo lo usa para magistrados civiles al servicio de los propósitos de Dios (Ro 13:6) y para su propio papel sacerdotal entre los gentiles (Ro 15:16).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71604, 'spa', 'Escamas oculares', 'Hechos 9:18 relata que, tras la imposición de manos de Ananías, algo semejante a escamas cayó de los ojos de Saulo y recobró la vista. Las traducciones multilingües (scales, escamas, écaille) preservan la imagen física, probablemente metafórica de la ceguera espiritual eliminada. Este momento dramático marca la conversión de Saulo, donde la vista restaurada simboliza una nueva percepción espiritual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71605, 'spa', 'Enfermedad cutánea ritual', 'Enfermedad grave de la piel caracterizada por descamación y desfiguración, que acarreaba impureza ritual según la Torá. Las cuatro apariciones neotestamentarias se encuentran en relatos de sanación: Jesús limpia leprosos con su toque y su palabra (Mt 8:3; Mc 1:42; Lc 5:12-13), revirtiendo tanto la aflicción física como el estigma social que la acompañaba.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71606, 'spa', 'Leproso', 'Leproso — persona afligida por una enfermedad cutánea desfigurante (griego λέπρα) que implicaba impureza ritual y exclusión social bajo la ley levítica (Lv 13-14). En el NT, la sanación de leprosos por Jesús es programática: el primer milagro tras el Sermón del Monte es la purificación de un leproso (Mt 8:2-4; Mc 1:40-45; Lc 5:12-14), y el informe «los leprosos son limpiados» valida las credenciales mesiánicas de Jesús (Mt 11:5; Lc 7:22).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71609, 'spa', 'Moneda mínima', 'El leptón, la moneda de cobre más pequeña en circulación. Marcos 12:42 y Lucas 21:2 relatan cómo Jesús observó a la viuda que dio «dos lepta» (todo lo que tenía) mientras los ricos ofrendaban de su abundancia. Jesús la elogió porque su entrega fue sacrificial, no proporcional: sus diminutas monedas representaban «todo su sustento». Lucas 12:59 lo emplea de forma proverbial para recalcar el pago completo hasta la última fracción.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71610, 'spa', 'Patriarca y nombre propio', 'Leví, nombre propio hebreo, designa ante todo al tercer hijo de Jacob y Lea, ancestro del sacerdocio levítico. En Heb 7:5, 9, el nombre fundamenta el argumento teológico de que el sacerdocio levítico es subordinado al de Melquisedec, pues Leví estaba aún «en el cuerpo de Abraham» cuando este diezmó. Ap 7:7 incluye la tribu de Leví entre los sellados.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71611, 'spa', 'Nombre propio', 'Leví, nombre propio de persona. En Marcos 2:14, Lucas 5:27 y 5:29 identifica al recaudador de impuestos que Jesús llamó a seguirle: «Leví hijo de Alfeo». Lucas 5:29 menciona que «Leví le hizo un gran banquete en su casa» tras su llamamiento. Este Leví suele identificarse con el apóstol Mateo (Mateo 9:9 llama «Mateo» al recaudador en el relato paralelo), lo que sugiere que pudo tener dos nombres.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71612, 'spa', 'Levita del templo', 'Levita, miembro de la tribu de Leví que asistía en el servicio del templo. Lucas 10:32 presenta a un levita en la parábola del buen samaritano que pasa de largo ante el herido, fallando como el sacerdote en mostrar misericordia. Juan 1:19 identifica a los interrogadores de Juan el Bautista como sacerdotes y levitas, autoridades religiosas oficiales. Hechos 4:36 presenta a Bernabé como levita de Chipre.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71613, 'spa', 'Sacerdocio levítico', 'Hebreos 7:11 cuestiona si la perfección podía alcanzarse mediante el sacerdocio levítico, puesto que la ley se fundamentaba en él. Esto prepara el argumento a favor del sacerdocio superior y eterno de Cristo. La evidencia multilingüe (Levitical, levítico, lévitique, levitisch) identifica uniformemente la forma adjetival relativa al oficio levítico, central en la teología de Hebreos sobre Cristo que supera la antigua alianza.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71615, 'spa', 'El color blanco como marca de gloria divina, pureza celestial y resplandor escat', 'El color blanco como marca de gloria divina, pureza celestial y resplandor escatologico en el uso neotestamentario. Describe las vestiduras de Jesus transfigurado (Mt. 17:2; Mr. 9:3), las ropas de los angeles en el sepulcro y la Ascension (Mt. 28:3; Mr. 16:5; Hch. 1:10), y el abrumador vocabulario visual de Apocalipsis: vestiduras blancas de los fieles (Ap. 3:4-5; 7:9, 13), caballos blancos de la guerra divina (Ap. 6:2; 19:11, 14), el gran trono blanco del juicio final (Ap. 20:11) y la piedrecita blanca con un nombre secreto (Ap. 2:17). El unico uso mundano es la observacion de Jesus de que los campos ya estan ''blancos'' para la siega (Jn. 4:35).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71618, 'spa', 'León', 'León — el gran felino depredador (Panthera leo), usado en el NT como símbolo de doble vertiente: imagen de peligro destructivo (1 P 5:8, el diablo ronda «como león rugiente»; 2 Ti 4:17, Pablo librado «de la boca del león») y figura de poder mesiánico regio (Ap 5:5, «el León de la tribu de Judá»).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71622, 'spa', 'Olvido espiritual', '2 Pedro 1:9 advierte que los creyentes carentes de cualidades espirituales son cortos de vista hasta la ceguera, habiendo caído en el olvido de su purificación de pecados pasados. Las traducciones multilingües (forgetfulness, olvido, λήθην, Vergessen) captan el lapsus cognitivo que Pedro describe. Este olvido no es simple distracción, sino una amnesia espiritual peligrosa sobre la identidad del creyente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71623, 'spa', 'Lagar literal y simbólico', 'Lagar o cuba de vino, artesa de piedra o madera donde se aplastan las uvas para extraer el mosto. En Mt 21:33 aparece en su sentido agrícola literal como parte del equipamiento de una viña. Apocalipsis lo despliega como símbolo devastador del juicio final de Dios: el ángel arroja la cosecha en «el gran lagar de la ira de Dios» (Ap 14:19) y la sangre fluye por 1.600 estadios (Ap 14:20).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71624, 'spa', 'Disparate o desatino', 'Lucas 24:11 registra la reacción inicial de los apóstoles ante el informe de las mujeres en la mañana de Pascua: sus palabras les parecieron un desatino y no les creyeron. La evidencia multilingüe (nonsense, delirio, baliverne) capta el desprecio desdeñoso implícito. Este momento pone de relieve tanto la naturaleza inesperada de la resurrección como las barreras culturales que las primeras testigos debieron enfrentar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71625, 'spa', 'Ladrón, bandido — saqueador o salteador que se apodera de bienes ajenos mediante', 'Ladrón, bandido — saqueador o salteador que se apodera de bienes ajenos mediante la violencia o la intimidación armada, claramente distinto del κλέπτης (ratero) que actúa con sigilo. Jesús aplica esta palabra a la economía corrupta del templo: «la habéis hecho cueva de ladrones» (Mt 21:13; Mc 11:17; Lc 19:46). Los dos crucificados junto a Cristo son llamados λῃσταί (Mt 27:38, 44), probablemente con matices de insurrección.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71630, 'spa', 'Recepción o ingreso', 'Filipenses 4:15 emplea terminología financiera, contrastando el dar y el recibir para describir la asociación única entre Pablo y la iglesia de Filipos. Las traducciones multilingües (receiving, recibir, λήμψεως, Empfang) reflejan la dimensión comercial del término. El lenguaje cuidadoso de Pablo reconoce su apoyo material mientras lo enmarca teológicamente como participación en el ministerio del evangelio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71631, 'spa', 'Muy, en gran manera — adverbio intensivo que eleva el grado de un verbo, adjetiv', 'Muy, en gran manera — adverbio intensivo que eleva el grado de un verbo, adjetivo u otro adverbio acompañante, traducible como «muy», «extremadamente» o «en gran manera». Modifica estados emocionales (Mt 2:16, Herodes «extremadamente» enfurecido; Mt 27:14, Pilato «grandemente» asombrado), cualidades físicas (Mt 4:8, un monte «extremadamente» alto; Mt 8:28, «sumamente» feroces), y marcadores temporales (Mc 1:35, «muy» de mañana; Mc 16:2, «muy» temprano).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71634, 'spa', 'Esclavo liberado', 'Hechos 6:9 menciona la Sinagoga de los Libertos entre quienes disputaban con Esteban. Estos eran probablemente judíos esclavizados por los romanos y luego liberados, o sus descendientes. Las traducciones multilingües (Freedmen, Libertînos, Libertins) preservan la designación latina, reflejando la realidad de la manumisión en el mundo romano y la diversa composición de la comunidad judía de Jerusalén.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71635, 'spa', 'Región norteafricana', 'Hechos 2:10 incluye a judíos libios entre la multitud internacional presente en Pentecostés que escuchó el evangelio en sus propias lenguas. La referencia a «las partes de Libia cercanas a Cirene» especifica la región de Cirenaica, un importante centro de asentamiento judío. La evidencia interlingüística (Libya, Libýes, Libye) preserva la antigua designación geográfica de este territorio norteafricano.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71636, 'spa', 'Apedrear como castigo', 'Apedrear o lanzar piedras como castigo, ejecución judicial o violencia de turba. El griego λιθάζω (de λίθος, «piedra») denota arrojar piedras con intención letal. En Juan 8:5 se cita la ley mosaica de lapidación por adulterio; en Juan 10:31-33 intentan apedrear a Jesús por blasfemia; Pablo fue apedreado en Listra (Hch 14:19).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71644, 'spa', 'Hecho de piedra', 'De piedra, construido con piedra. Juan 2:6 describe seis tinajas de piedra para la purificación judía en Caná, donde Jesús transformó agua en vino; los recipientes de piedra no contraían impureza ritual. 2 Corintios 3:3 contrasta la palabra de Dios escrita «no en tablas de piedra sino en corazones humanos», distinguiendo la ley mosaica externa de la transformación interior obrada por el Espíritu.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71645, 'spa', 'Apedrear, lapidar', 'Arrojar piedras contra una persona como ejecución judicial o castigo comunitario prescrito por la Torá. Las siete apariciones neotestamentarias implican intención mortal. En Mt 23:37 y Lc 13:34 Jesús llora por la costumbre de Jerusalén de apedrear a los mensajeros de Dios; en Hch 7:58-59 la lapidación de Esteban se convierte en el martirio paradigmático.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71650, 'spa', 'piedra / roca (general)', 'Piedra o roca en todo su espectro: rocas naturales (Mt 3:9; 4:3), sillares del templo (Mr 13:1-2), la piedra del sepulcro (Mt 27:60; 28:2), gemas preciosas (Ap 21:19) y proyectiles de lapidación (Jn 8:59; Hch 7:58-59). Figuradamente, la piedra angular rechazada (Mt 21:42), piedra de tropiezo (Ro 9:33) y piedra viva (1 P 2:4-5).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71655, 'spa', 'Pavimento de piedra', 'Juan 19:13 identifica el Litóstrotos como el lugar específico donde Pilato emitió su veredicto sobre Jesús. La precisión arquitectónica del término, referido a un pavimento de piedras encajadas, coincide con los hallazgos arqueológicos de espacios administrativos romanos. Las traducciones multilingües (Stone-Pavement, Empedrado, Lithostrotos, Steinpflaster) preservan tanto la forma descriptiva como la transliterada, marcando este sitio como un lugar histórico decisivo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71657, 'spa', 'Puerto marítimo', 'Puerto o refugio donde los barcos anclan para resguardarse. Las tres apariciones se hallan en Hechos 27, durante el viaje de Pablo a Roma. El barco llegó a Buenos Puertos (27:8), puerto inadecuado para invernar, y decidieron navegar hacia Fenice, un puerto mejor en Creta (27:12). El intento de alcanzar ese puerto provocó la devastadora tempestad y el naufragio, aunque Dios preservó a todos a bordo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71658, 'spa', 'Lago — un cuerpo natural de agua dulce estancada, específicamente el lago de Gen', 'Lago — un cuerpo natural de agua dulce estancada, específicamente el lago de Genesaret (Mar de Galilea) en el Evangelio de Lucas. Lucas emplea λίμνη donde Mateo y Marcos escriben θάλασσα (''mar''), reflejando el uso geográfico del griego culto. Aparece en el llamado de los primeros discípulos (Lc 5:1-2), el apaciguamiento de la tormenta (Lc 8:22-23) y el relato del endemoniado gadareno (Lc 8:33). El español ''lago'' y el francés ''lac'' corresponden exactamente al término.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71659, 'spa', 'Hambre / hambruna — privación severa de alimentos, que abarca desde la hambruna ', 'Hambre / hambruna — privación severa de alimentos, que abarca desde la hambruna generalizada que afecta regiones enteras hasta el hambre y la inanición personal. Aparece en advertencias escatológicas como uno de los dolores de parto que señalan el fin (Mt 24:7, «habrá hambres»; Ap 6:8, la hambruna como arma de los cuatro jinetes), en relatos históricos (Lc 4:25, la hambruna de tres años y medio; Hch 11:28, la hambruna bajo Claudio), y en la experiencia íntima del hijo pródigo (Lc 15:14, 17).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71664, 'spa', 'Cristiano romano', '2 Timoteo 4:21 incluye a Lino entre los cristianos romanos que envían saludos a Timoteo. Padres de la Iglesia como Ireneo lo identifican como primer obispo de Roma tras los apóstoles, aunque si es la misma persona sigue debatiéndose. La evidencia multilingüe preserva el nombre con mínima variación, situando a Lino en la comunidad apostólica de Roma.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71665, 'spa', 'Cosas suntuosas', 'Apocalipsis 18:14 declara que los frutos que el alma de Babilonia codiciaba se han ido, y todas sus cosas lujosas y espléndidas han perecido. Las glosas multilingües (luxurious-things, suntuosas, précieux, kostbar) captan el sentido de indulgencia costosa. Este oráculo de juicio emplea lenguaje comercial para retratar el colapso de un sistema edificado sobre el materialismo y la explotación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71667, 'spa', 'Viento del suroeste', 'Hechos 27:12 emplea este término para describir la orientación del puerto de Buenos Puertos en Creta durante el viaje de Pablo. La precisión náutica refleja la atención meticulosa de Lucas a los detalles de navegación. Las glosas multilingües varían entre interpretaciones direccionales (southwest, suroeste) y regionales (Lycie), aunque el sentido meteorológico-geográfico del suroeste es el primario en este contexto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71669, 'spa', 'Acreditar, imputar o abonar en la cuenta de alguien', 'Acreditar, imputar o abonar en la cuenta de alguien. Es el uso teologico central de Pablo en Romanos 4, donde la fe de Abraham ''le fue contada por justicia'' (Ro 4:3, 5, 9, 22). Predomina la voz pasiva con Dios como agente implicito. Marcos 15:28 y Lucas 22:37 citan Isaias 53:12: ''fue contado con los transgresores''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71670, 'spa', 'Considerar, evaluar o estimar que alguien o algo posee determinado caracter o co', 'Considerar, evaluar o estimar que alguien o algo posee determinado caracter o condicion. Romanos 3:28 lo usa para la conclusion de un argumento razonado (''concluimos que el hombre es justificado por la fe''), y Romanos 6:11 exhorta a los creyentes a ''considerarse muertos al pecado''. Es el sentido de juicio cognitivo activo donde el sujeto forma una valoracion.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71675, 'spa', 'Pensar, razonar o deliberar', 'Pensar, razonar o deliberar: el sentido puramente cognitivo de procesamiento mental. Pablo lo emplea en 2 Corintios 10:2 respecto a quienes ''piensan'' de el, y en 1 Corintios 13:11 sobre el razonamiento infantil. Juan 11:50 muestra a Caifas ''considerando'' la conveniencia politica. Aqui el verbo carece de connotacion contable.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71700, 'spa', 'Oráculo divino', 'Declaración divina o cuerpo de revelaciones habladas por Dios. En Hch 7:38 Esteban describe a Moisés recibiendo «oráculos vivientes» en el Sinaí — palabras pulsantes de autoridad divina. Ro 3:2 señala estos oráculos como el gran privilegio de Israel. Heb 5:12 los trata como enseñanza fundamental, y 1 Pe 4:11 los establece como norma para el hablar cristiano.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71701, 'spa', 'Elocuente y erudito', 'Hechos 18:24 presenta a Apolos como un varón elocuente, versado en las Escrituras. Alejandría era célebre por su tradición intelectual, y Apolos encarnaba ese legado. La evidencia multilingüe (eloquent, elocuente, éloquent) resalta la habilidad retórica, aunque el término también sugiere un saber más amplio. La instrucción posterior de Priscila y Aquila demuestra que la elocuencia sin conocimiento evangélico completo resulta insuficiente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71703, 'spa', 'Disputar sobre palabras', '2 Timoteo 2:14 instruye a Timoteo a exhortar a los creyentes ante Dios a no enzarzarse en batallas de palabras, que no aprovechan para nada y conducen a la ruina de quienes escuchan. Las glosas multilingües (quarrel-about-words, discutir-sobre-palabras, λογομαχεῖν, Wortstreit) captan la naturaleza contenciosa e improductiva de tales disputas. Pablo advierte consistentemente contra controversias verbales que distraen de la verdad evangélica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71704, 'spa', 'Disputas de palabras', '1 Timoteo 6:4 describe a los falsos maestros como personas con un afán morboso por controversias y disputas de palabras, las cuales producen envidia, disensión, calumnias y malas sospechas. La evidencia multilingüe (word-battles, disputas-de-palabras, λογομαχίας, Wortstreit) subraya la naturaleza combativa e inedificante de tales argumentos. Pablo considera estas contiendas verbales como síntomas de una enfermedad espiritual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71705, 'spa', 'palabra, mensaje, discurso', 'Comunicación hablada o escrita: «palabra», «mensaje», «discurso», «enseñanza» o «proclamación». Con 309 apariciones es la acepción dominante, que abarca los dichos de Jesús («sea vuestro hablar sí, sí», Mt 5:37), la «palabra del reino» de las parábolas (Mt 13:19) y la predicación apostólica («la palabra de Dios»). Todas las lenguas principales la vierten con un solo término nuclear: palabra (esp.), parole (fr.), Wort (al.).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71708, 'spa', 'el Logos, Verbo divino', 'El Logos: la Palabra divina preexistente y encarnada, título cristológico exclusivo de la literatura joánica. Siete apariciones —Jn 1:1 (tres veces), 1:14, 1 Jn 1:1 y Ap 19:13— establecen a Jesús como autoexpresión de Dios desde la eternidad. El español revela la carga teológica al ofrecer tres traducciones distintas: Palabra, Verbo (término teológico latino de la Vulgata) y el préstamo directo Lógos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71709, 'spa', 'cuenta, rendición', 'Una rendición de cuentas financiera o moral: «cuenta», como en ajustar cuentas o rendir cuenta ante un juez o ante Dios. Once apariciones se agrupan en parábolas de juicio: el rey que «ajustó cuentas» con sus siervos (Mt 18:23; 25:19) y el mayordomo al que se le pide «dar cuenta» (Lc 16:2). El español distingue nítidamente cuenta/cuentas y razón, haciendo visible un sentido que palabra oculta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71713, 'spa', 'razón, causa, asunto', 'El fundamento, razón o causa de algo, o un asunto en disputa. Cinco apariciones emplean λόγος donde el español diría «razón» o «causa»: la cláusula «excepto por causa de fornicación» (Mt 5:32), Festo buscando un «cargo» que presentar (Hch 25:26) y Pedro exhortando a tener «razón» de la esperanza (1 P 3:15). El español razón y causa captan este vínculo con la argumentación racional.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71725, 'spa', 'Injuriar verbalmente', 'Ultrajar con palabras, lanzar insultos despectivos contra alguien. Los fariseos injurian al ciego sanado por ser discípulo de Jesús (Jn 9:28); Pablo es reprendido por ultrajar inadvertidamente al sumo sacerdote (Hch 23:4). En 1 Co 4:12 Pablo responde a la injuria con bendición, y 1 Pe 2:23 presenta a Cristo como modelo: «cuando le injuriaban, no respondía con injuria».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71726, 'spa', 'Injuria verbal', 'Abuso verbal, insulto, injuria o reproche. 1 Timoteo 5:14 advierte que la conducta impropia de viudas jóvenes podría dar al adversario motivo de reproche contra la iglesia. 1 Pedro 3:9 manda dos veces a los creyentes «no devolver mal por mal ni injuria por injuria, sino al contrario, bendiciendo», enseñando una respuesta radicalmente contracultural ante el abuso verbal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71729, 'spa', 'Las personas restantes, los demas de un grupo, usado sustantivamente', 'Las personas restantes, los demas de un grupo, usado sustantivamente. Jesus distingue a los discipulos de ''los demas'' que reciben la ensenanza en parabolas (Lc 8:10); Pablo se refiere a ''los demas apostoles'' (1 Co 9:5); Apocalipsis habla repetidamente de ''los demas'' que no fueron afectados por las plagas. Es el sentido partitivo de quienes quedan tras seleccionar un subgrupo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71732, 'spa', 'Las cosas restantes, los asuntos o elementos que quedan, usado sustantiva o atri', 'Las cosas restantes, los asuntos o elementos que quedan, usado sustantiva o atributivamente con referentes no personales. Marcos 4:19 advierte que ''los deseos por las demas cosas'' ahogan la palabra; Pablo dice a los corintios ''las demas cosas las arreglare cuando llegue'' (1 Co 11:34). El enfasis recae en lo que queda pendiente o sin tratar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71745, 'spa', 'Finalmente, además — marcador discursivo que introduce nuevas instrucciones o ci', 'Finalmente, además — marcador discursivo que introduce nuevas instrucciones o cierra un argumento. Pablo usa τὸ λοιπόν para pasar a instrucciones nuevas o concluir una argumentación (1 Co 1:16; 4:2; 2 Co 13:11; Fil 3:1; 4:8). En Hch 27:20, marca un giro narrativo: «finalmente se abandonó toda esperanza».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71748, 'spa', 'Restante, lo demás — uso adjetival o sustantivado que indica lo que queda o sobr', 'Restante, lo demás — uso adjetival o sustantivado que indica lo que queda o sobra. Jesús dice a los discípulos que duerman «el tiempo restante» en Getsemaní (Mt 26:45; Mc 14:41), Pablo afirma que «el tiempo restante es corto» (1 Co 7:29), y Hebreos 10:13 habla de esperar hasta que los enemigos sean puestos como estrado «en lo que resta».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71751, 'spa', 'En adelante, de ahora en más — adverbio temporal que marca una transición en el ', 'En adelante, de ahora en más — adverbio temporal que marca una transición en el tiempo. En 2 Ti 4:8, Pablo declara que «en adelante» le está reservada la corona de justicia, señalando una transición temporal más que discursiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71756, 'spa', 'Lucas, médico amado', 'Lucas, compañero de Pablo y «médico amado» (Colosenses 4:14). Este creyente gentil viajó con Pablo durante parte de sus misiones (evidente en los pasajes con «nosotros» de Hechos) y es autor del Evangelio de Lucas y de Hechos. En el último encarcelamiento de Pablo, cuando casi todos lo habían abandonado, «solo Lucas está conmigo» (2 Timoteo 4:11), demostrando lealtad fiel. Filemón 24 lo incluye entre los colaboradores de Pablo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71759, 'spa', 'Bañar el cuerpo entero', 'Lavar o bañar todo el cuerpo — una limpieza completa en contraste con un lavado parcial. Jn 13:10 establece la distinción léxica clave con νίπτω: quien ha sido bañado completamente solo necesita un lavado parcial. Hechos lo emplea para la preparación postmortem (9:37) y el lavado de heridas (16:33). Heb 10:22 lo aplica metafóricamente a la purificación espiritual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71760, 'spa', 'Ciudad de Judea', 'Lida, ciudad de Judea en la llanura costera. Hechos 9:32 relata la visita de Pedro: «pasando por todos aquellos lugares, vino también a los santos que habitaban en Lida». Allí sanó a Eneas, paralítico por ocho años (9:33-34), lo que produjo una conversión masiva: «todos los que habitaban en Lida y en Sarón le vieron, y se convirtieron al Señor» (9:35). Desde Lida, los discípulos llamaron a Pedro a Jope.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71762, 'spa', 'Región de Licaonia', 'Hechos 14:6 relata que Pablo y Bernabé huyeron de la persecución en Iconio hacia las ciudades de Licaonia: Listra y Derbe. La singularidad cultural de esta región se evidencia en Hechos 14:11, donde los habitantes hablaron en licaonio tras presenciar el milagro de Pablo. Este territorio interior de Anatolia fue significativo en la expansión del cristianismo primitivo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71763, 'spa', 'En idioma licaonio', 'Hechos 14:11 señala que la multitud licaonia habló en su lengua nativa, la cual Pablo y Bernabé aparentemente no comprendieron de inmediato, lo que provocó confusión sobre los preparativos de sacrificio. Este detalle resalta la diversidad lingüística del mundo antiguo y los desafíos comunicativos que enfrentaban los misioneros en territorios culturalmente distintos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71764, 'spa', 'Región de Licia', 'Hechos 27:5 relata que la nave de Pablo llegó a Mira, un puerto importante de Licia, durante el peligroso viaje hacia Roma. Licia ocupaba una posición estratégica en las rutas comerciales del Mediterráneo. Esta región costera del suroeste de Anatolia constituye una etapa clave en el viaje marítimo de Pablo como prisionero rumbo a la capital imperial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71765, 'spa', 'Lobo', 'Un lobo, el canino depredador salvaje, empleado tanto en sentido literal como figurado. Literalmente designa al animal salvaje que amenaza los rebaños, como en John 10:12 donde el lobo arrebata y dispersa las ovejas. Figuradamente, Jesús lo usa para caracterizar a los falsos profetas disfrazados con piel de oveja (Matt 7:15) y el mundo hostil al que los discípulos son enviados (Matt 10:16; Luke 10:3).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71768, 'spa', 'Devastar violentamente', 'Hechos 8:3 emplea este verbo enérgico para describir la persecución de Saulo antes de su conversión: asolaba la iglesia, irrumpiendo en los hogares y encarcelando a los creyentes. La intensidad violenta del término captura el celo de Saulo como perseguidor, haciendo que su posterior transformación en el apóstol Pablo resulte aún más extraordinaria y testimonio de la gracia divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71769, 'spa', 'Estar entristecido, sentir pesar o angustia como respuesta emocional', 'Estar entristecido, sentir pesar o angustia como respuesta emocional. Este uso intransitivo o pasivo domina en el NT (unas 20 ocurrencias). Los discipulos se entristecen ante las predicciones de la Pasion (Mt. 17:23), Herodes se entristece por su juramento (Mt. 14:9) y el joven rico se va entristecido (Mt. 19:22). El aleman ''betruebt-werden'' (entristecerse) resalta la cualidad pasiva y vivencial de este sentido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71772, 'spa', 'Entristecer a alguien, causar pesar en otra persona', 'Entristecer a alguien, causar pesar en otra persona. Un uso transitivo y causativo que se encuentra especialmente en las cartas de Pablo a Corinto, donde el apostol reflexiona sobre si su carta causo dolor (2 Co. 2:2, 2:5, 7:8). El espanol distingue esto con claridad: ''entristecio'' (el entristecio a alguien) frente al reflexivo ''se entristecio'' (el se puso triste). El uso implica peso moral: uno es responsable de la afliccion que causa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71788, 'spa', 'Tristeza, dolor, pena', 'Tristeza, dolor, pena: Angustia emocional profunda que abarca aflicción, tristeza y dolor del corazón. El discurso de despedida joánico ofrece el retrato más completo: la tristeza llena los corazones de los discípulos por la partida de Jesús, pero será transformada en gozo inquebrantable (Jn 16:6, 20-22). Pablo desarrolla una teología de la λύπη, distinguiendo una tristeza según Dios que produce arrepentimiento de una tristeza del mundo que produce muerte (2 Co 7:10). Los discípulos en Getsemaní duermen agobiados por la tristeza (Lc 22:45).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71791, 'spa', 'Tetrarca de Abilene', 'Lucas 3:1 incluye a Lisanias entre los gobernantes que anclan la cronología del ministerio de Juan el Bautista. Al nombrar múltiples autoridades seculares —romana, herodiana y local— Lucas establece un contexto histórico preciso. Lisanias, como tetrarca de Abilene, proporciona el marco temporal para los eventos inaugurales del evangelio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71792, 'spa', 'Tribuno romano', 'Lisias, específicamente Claudio Lisias, el tribuno romano (comandante militar) estacionado en Jerusalén. Hechos 23:26 conserva su carta a Félix: «Claudio Lisias al excelentísimo gobernador Félix: Salud». Rescató a Pablo de una turba judía (21:31-32), descubrió un complot contra su vida y lo trasladó a salvo a Cesarea. Hechos 24:7, 22 lo mencionan en el contexto del juicio de Pablo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71793, 'spa', 'Liberación del matrimonio', 'En 1 Corintios 7:27, Pablo plantea preguntas paralelas: ¿Estás ligado a una esposa? No busques la separación. ¿Has sido liberado? No busques casarte. Su consejo responde a la ''angustia presente'' y prioriza la devoción íntegra al Señor. Las traducciones multilingües (separación, délivrance, Lösung) captan el sentido de disolución o libertad del vínculo matrimonial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71794, 'spa', 'Conveniencia o ventaja', 'En Lucas 17:2, Jesús declara que sería más provechoso para un ofensor ser arrojado al mar que hacer pecar a un creyente. Las traducciones multilingües (conviene, il vaut mieux, es mejor) captan el sentido comparativo. La advertencia hiperbólica resalta la gravedad de inducir a otros al pecado, midiendo las consecuencias eternas frente al castigo físico más severo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71795, 'spa', 'Listra', 'Nombre propio de una ciudad en Licaonia, centro-sur de Asia Menor (actual Turquía). Pablo y Bernabé huyeron allí desde Iconio (Acts 14:6), convirtiéndose en lugar clave de sus viajes misioneros. Sitio de una sanidad milagrosa y del apedreamiento casi fatal de Pablo (Acts 14:8-19), y ciudad natal de Timoteo (Acts 16:1-2).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71798, 'spa', 'Redimir, rescatar', 'Redimir, rescatar o liberar mediante el pago de un precio. Los discípulos desilusionados de Emaús dijeron de Jesús: «nosotros esperábamos que él era el que había de redimir a Israel» (Lucas 24:21), esperando una liberación político-nacional. Tito 2:14 explica que Jesús «se dio a sí mismo por nosotros para redimirnos de toda iniquidad y purificar para sí un pueblo propio», comprando la libertad de la esclavitud del pecado. Primera Pedro 1:18 subraya el costo incomparable del rescate.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71799, 'spa', 'Redención divina', 'Redención, rescate o liberación. La profecía de Zacarías bendice a Dios porque «ha visitado y redimido a su pueblo» (Lucas 1:68), celebrando la redención cumplida en la venida del Mesías. Ana habló «de él a todos los que esperaban la redención en Jerusalén» (Lucas 2:38), a quienes anhelaban la liberación de Israel. Hebreos 9:12 contrasta la entrada de Cristo al lugar santísimo «por su propia sangre», obteniendo así «eterna redención».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71800, 'spa', 'Redentor o libertador', 'En Hechos 7:35, Moisés es descrito como aquel a quien Israel rechazó, pero a quien Dios envió como gobernante y redentor mediante el ángel de la zarza ardiente. Esteban destaca el patrón de Israel de rechazar a los libertadores divinos. Las traducciones multilingües (redentor, libérateur, Erlöser) captan el tema de liberación propio del Éxodo y la tipología cristiana primitiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71801, 'spa', 'Candelero / candelabro — soporte o estructura diseñada para elevar una lámpara y', 'Candelero / candelabro — soporte o estructura diseñada para elevar una lámpara y que ilumine un espacio, usado tanto literal como simbólicamente. En los dichos sinópticos, Jesús lo emplea como metáfora del discipulado visible: la lámpara pertenece al candelero, no debajo de un almud (Mt 5:15; Mc 4:21; Lc 8:16). Hebreos 9:2 se refiere a la menorá de oro del tabernáculo. En Apocalipsis, siete candeleros de oro simbolizan las siete iglesias (Ap 1:12-13, 20; 2:1, 5), y los dos testigos son llamados dos candeleros (Ap 11:4).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71805, 'spa', 'Lámpara / luz — lámpara portátil de aceite, la fuente de iluminación doméstica e', 'Lámpara / luz — lámpara portátil de aceite, la fuente de iluminación doméstica estándar del mundo antiguo, colocada sobre un candelero para alumbrar la estancia. Usada literalmente para el objeto físico (Mt 5:15; Mc 4:21; Lc 8:16; 11:33; 15:8; Ap 18:23) y figuradamente para fuentes de luz espiritual: el ojo como la lámpara del cuerpo (Mt 6:22; Lc 11:34, 36), Juan el Bautista como lámpara que arde (Jn 5:35), y el Cordero como lámpara escatológica (Ap 21:23).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71808, 'spa', 'Desatar, desligar o soltar fisicamente algo que esta atado', 'Desatar, desligar o soltar fisicamente algo que esta atado. Los discipulos desatan un asno y su pollino (Mt 21:2; Mr 11:2-4; Lc 19:30-33); Lazaro es desatado de sus vendas funerarias (Jn 11:44); las cadenas de Pablo se sueltan (Hch 16:26). El logion de atar y desatar de Mateo 16:19 y 18:18 se situa formalmente aqui pero irradia al ambito juridico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71809, 'spa', 'Disolver, derretir o desintegrar, agrupado en contextos escatologicos', 'Disolver, derretir o desintegrar, agrupado en contextos escatologicos. En 2 Pedro 3:10-12, los cielos ''seran disueltos'' por fuego y los elementos ''se derretiran con calor ferviente''; en Hechos 27:41 la popa del barco ''se rompia'' bajo las olas. Este sentido marca el caracter irreversible y entropico de la destruccion.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71815, 'spa', 'Quebrantar, violar o anular una ley, mandamiento o Escritura', 'Quebrantar, violar o anular una ley, mandamiento o Escritura. Jesus advierte que quien ''quebrante'' uno de los mandamientos mas pequenos sera llamado menor en el reino (Mt 5:19); lo acusan de ''quebrantar'' el sabado (Jn 5:18); el arguye que la Escritura ''no puede ser quebrantada'' (Jn 10:35). Sentido juridico-normativo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71817, 'spa', 'Liberar o poner en libertad a una persona de ataduras, enfermedad u obligacion', 'Liberar o poner en libertad a una persona de ataduras, enfermedad u obligacion. Jesus ''libera'' a la mujer encorvada de dieciocho anos de esclavitud satanica (Lc 13:16); Dios ''desato los dolores de la muerte'' al resucitar a Cristo (Hch 2:24); Pablo pregunta si uno ''ha sido suelto'' de su esposa (1 Co 7:27). El enfasis pasa del nudo fisico al estado de cautividad que termina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71821, 'spa', 'Destruir, derribar o demoler una estructura o sistema', 'Destruir, derribar o demoler una estructura o sistema. Jesus desafia a las autoridades: ''Destruid este templo y en tres dias lo levantare'' (Jn 2:19); Cristo ''derribo la pared intermedia de separacion'' (Ef 2:14); el Hijo de Dios aparecio ''para destruir las obras del diablo'' (1 Jn 3:8).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71836, 'spa', 'Disolver o despedir una asamblea', 'Disolver o despedir una asamblea. Uso singular y transitorio en Hechos 13:43, donde ''disuelta la congregacion'' describe la dispersion de los asistentes tras la reunion de la sinagoga. La congregacion reunida es ''desatada'' de vuelta a sus miembros individuales, un sentido bien atestiguado en el griego secular.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71842, 'spa', 'Nombre propio femenino', 'En 2 Timoteo 1:5, Pablo recuerda la fe sincera que habitó primero en Loida, luego en Eunice y finalmente en Timoteo mismo. La referencia afectuosa de Pablo honra a las mujeres fieles que lo formaron espiritualmente. Las traducciones multilingües preservan el nombre con variaciones mínimas, reconociendo a Loida como ejemplo del papel vital de las abuelas en la fe.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71843, 'spa', 'Lot (nombre propio)', 'Nombre propio de Lot, sobrino de Abraham, usado en el NT como figura tipológica del juicio y la liberación divinos. En Lc 17:28-29 Jesús compara la destrucción de Sodoma con la venida del Hijo del Hombre. Lc 17:32 advierte contra mirar atrás. En 2 Pe 2:7 Lot es llamado «justo», rescatado de los impíos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71844, 'spa', 'Nombre propio masculino', 'Maát aparece una sola vez en Lucas 3:26, representando un eslabón en la genealogía ascendente que traza el linaje de Jesús a través del judaísmo postexílico hasta David y finalmente hasta Adán. La evidencia multilingüe trata uniformemente este término como un nombre propio transliterado, con traducciones consistentes entre idiomas que reflejan la oscuridad de este personaje en los registros históricos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71845, 'spa', 'Región galileana costera', 'Mateo 15:39 relata que tras despedir a las multitudes, Jesús subió a la barca y se dirigió a la región de Magadán. Las variantes textuales generan incertidumbre sobre su ubicación precisa. Las glosas multilingües (Magadan, Magadán) preservan el nombre, reconociéndolo como un distrito costero galileano, posiblemente idéntico a Magdala o cercano a ella.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71846, 'spa', 'Magdalena — epíteto geográfico que significa «de Magdala», usado exclusivamente ', 'Magdalena — epíteto geográfico que significa «de Magdala», usado exclusivamente para identificar a María Magdalena, distinguiéndola de María la madre de Jesús y de otras mujeres llamadas María. Derivado de la ciudad galileana de Magdala (hebreo migdal, «torre»). Presente en la crucifixión (Mt 27:56; Mc 15:40; Jn 19:25), en la sepultura (Mt 27:61; Mc 15:47), en el sepulcro vacío (Mt 28:1; Mc 16:1; Lc 24:10; Jn 20:1) y como primera testigo de la resurrección (Jn 20:18).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71847, 'spa', 'Artes mágicas ocultas', 'Hechos 8:11 explica que Simón había asombrado a los samaritanos con su magia durante un tiempo considerable, llevándolos a considerarlo «el Gran Poder de Dios». Las glosas multilingües (magic-arts, magias, magie) captan la dimensión ocultista. El posterior encuentro de Simón con Pedro revela la incompatibilidad entre el genuino poder espiritual y las prácticas mágicas manipuladoras.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71848, 'spa', 'Ejercicio de hechicería', 'Hechos 8:9 presenta a Simón como un hombre que venía practicando la magia en Samaria, asombrando a la población y pretendiendo ser alguien importante. Las glosas multilingües (practicing-magic, practicando-magia, pratiquer-la-magie) enfatizan la naturaleza activa y continua de su hechicería. Esta caracterización establece el contraste dramático cuando Simón encuentra el verdadero poder apostólico e intenta comprar el don del Espíritu Santo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71849, 'spa', 'Magos sabios', 'Un mago en el sentido honorable: sabio o sacerdote del Oriente, vinculado al saber persa en astronomía e interpretación de sueños. Las cuatro apariciones neotestamentarias están en Matthew 2, donde los Magos siguen una estrella para adorar al rey recién nacido (Matt 2:1, 7, 16). No son adivinos, sino representantes de la sabiduría pagana que se inclina ante el Mesías.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71850, 'spa', 'Hechicero charlatán', 'Un mago, hechicero o charlatán: la extensión peyorativa del término a quien practica artes mágicas, especialmente en oposición al verdadero poder divino. En Acts 13:6 Bar-Jesús es descrito como ''mago, falso profeta judío'', y en Acts 13:8 Elimas ''el mago'' resiste activamente a Pablo y Bernabé. En estos contextos el español ''mago'' porta la carga negativa de poder sobrenatural fraudulento.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71852, 'spa', 'Nación escatológica enemiga', 'Apocalipsis 20:8 utiliza Gog y Magog para representar a las naciones de los cuatro confines de la tierra congregadas para la guerra escatológica contra los santos. Apoyándose en la profecía de Ezequiel, Juan emplea estos nombres simbólicamente para designar la oposición final contra el reino de Dios. Las glosas multilingües preservan el nombre propio como parte de la imaginería apocalíptica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71853, 'spa', 'Territorio desértico madianita', 'La forma genitiva «de Madián» identifica el territorio desértico donde Moisés vivió como pastor durante cuarenta años antes de su llamamiento. La consistencia interlingüística (en español «de-Madiám», en francés «Madian») confirma esta como la forma estándar del NT para el topónimo hebreo, marcando una transición crucial en la vida de Moisés: de príncipe egipcio a pastor en el desierto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71854, 'spa', 'Hacer discípulos', 'Hacer de alguien un discípulo o someterse a formación discipular. La Gran Comisión (Mt 28:19) emplea el imperativo «haced discípulos a todas las naciones», estableciéndolo como verbo misionero central. Mt 27:57 describe a José de Arimatea como «hecho discípulo» de Jesús. Mt 13:52 presenta un escriba «instruido para el reino». En Hch 14:21 Pablo y Bernabé hacen discípulos en Derbe.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71855, 'spa', 'discípulo, aprendiz', 'Aprendiz y seguidor comprometido, vinculado personalmente a un maestro. Se usa de modo abrumador para los seguidores de Jesús en los Evangelios y Hechos (Mt 5:1; 8:21). Se extiende a discípulos de Juan el Bautista (Jn 1:35) y de los fariseos (Mt 22:16), conservando el sentido clásico de alumno bajo la tutela de un maestro. El término subraya el vínculo relacional de discipulado más allá del mero aprendizaje.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71860, 'spa', 'Discípula femenina', 'El nominativo singular femenino designa a Tabita como aprendiz y seguidora del camino de Jesús. La evidencia multilingüe (español ''discípula,'' francés ''disciple'') muestra que los traductores reconocen este término como la contraparte femenina del común μαθητής, subrayando que el discipulado no era exclusivamente masculino en la comunidad cristiana primitiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71861, 'spa', 'Patriarca antediluviano', 'La forma genitiva sitúa a este patriarca antediluviano dentro de la cadena de ascendencia de Jesús. La consistencia multilingüe en preservar la forma griega refleja el tratamiento habitual de los nombres propios en las genealogías, donde la transliteración en lugar de la traducción conserva el registro histórico que vincula la era primigenia con la mesiánica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71862, 'spa', 'Antepasado de Jesús', 'La forma genitiva sitúa a este individuo dentro de la cadena de descendencia de David a José. La consistencia multilingüe en preservar la forma griega refleja el tratamiento habitual de los nombres propios en las genealogías, donde la transliteración en lugar de la traducción preserva el registro histórico del linaje davídico de Jesús.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71863, 'spa', 'Estar loco o demente', 'Estar loco, demente o fuera de sí — exhibir un comportamiento que los observadores juzgan como desquiciado o irracional. En cada aparición en el NT, la acusación de locura recae sobre alguien cuyas palabras o acciones parecen demasiado extraordinarias para ser cuerdas. Jesús es llamado loco por sus osadas afirmaciones (Juan 10:20); Rode es desestimada como demente por su gozoso informe (Hechos 12:15); Pablo es acusado de locura por exceso de erudición (Hechos 26:24).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71865, 'spa', 'bienaventurado, dichoso', 'Adjetivo de pronunciamiento divino que declara a alguien favorecido, bendecido o privilegiado ante los ojos de Dios, empleado en macarismos (fórmulas de bienaventuranza) que invierten las expectativas del mundo. El Sermón del Monte (Mt 5:3-11) establece el patrón: quienes lloran, tienen hambre de justicia y padecen persecución son declarados μακάριοι porque de ellos es el reino de los cielos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71870, 'spa', 'Bienaventuranza', 'Bienaventuranza, estado de ser bendecido o favorecido por Dios. Romanos 4:6, 9 la emplea dos veces en el argumento de Pablo sobre la justificación: David habla de «la bienaventuranza del hombre a quien Dios atribuye justicia sin obras», el dichoso estado de quienes son declarados justos por fe, no por mérito. Pablo pregunta si esta bienaventuranza se extiende más allá de los judíos a los gentiles (4:9), respondiendo que Abraham creyó antes de la circuncisión.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71871, 'spa', 'La provincia romana en el norte de Grecia, un sitio importante de la mision paul', 'La provincia romana en el norte de Grecia, un sitio importante de la mision paulina. Todas las formas casuales se refieren a la misma entidad geografica. A menudo se empareja con Acaya para designar toda Grecia (Ro. 15:26; 1 Ts. 1:7-8). El llamado macedonico (Hch. 16:9) y la generosidad de las iglesias macedonias (2 Co. 8:1; Fil. 4:15) son momentos definitorios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71875, 'spa', 'Macedonio, de Macedonia', 'Macedonio — natural o habitante de la provincia romana de Macedonia en el norte de Grecia. El término funciona como gentilicio (identificador étnico y regional) y ocasionalmente como sinécdoque de las iglesias macedonias. En Hechos 16:9, el hombre macedonio de la visión de Pablo se convierte en el catalizador para la entrada del evangelio en Europa. Entre los macedonios nombrados están Aristarco y Gayo (Hechos 19:29; 27:2).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71876, 'spa', 'Mercado de carne', 'El dativo singular indica el lugar donde se vende la carne: ''en el mercado.'' Las traducciones oscilan entre el genérico ''mercado'' (español ''mercado'') y el específico ''carnicería'' (francés ''boucherie,'' alemán ''Fleischmarkt''), reflejando la naturaleza especializada de estos establecimientos donde frecuentemente se vendía como alimento común carne previamente ofrecida en sacrificios paganos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71877, 'spa', 'Lejos', 'Distancia espacial o lejanía respecto de un punto de referencia, con uso adverbial. En Mateo 8:30 un hato de cerdos pace «lejos»; en Juan 21:8 los discípulos no están «lejos de tierra». Marcos 12:34 extiende la metáfora espacial al ámbito espiritual, donde la proximidad al reino de Dios se expresa como cercanía figurada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71879, 'spa', 'De lejos / a distancia — adverbio de distancia espacial que significa «desde lej', 'De lejos / a distancia — adverbio de distancia espacial que significa «desde lejos» o «a distancia», usado para describir a observadores que están físicamente separados de la escena que presencian. Marca la distancia cautelosa de Pedro siguiendo tras el arresto de Jesús (Mt 26:58; Mc 14:54; Lc 22:54), la distancia doliente de las mujeres en el Calvario (Mt 27:55; Mc 15:40), el endemoniado que vio a Jesús μακρόθεν y corrió hacia él (Mc 5:6), y la reverente lejanía del publicano que no se atrevía a acercarse (Lc 18:13).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71881, 'spa', 'Ser paciente, ejercer longanimidad o tolerancia prolongada', 'Ser paciente, ejercer longanimidad o tolerancia prolongada: soportar la provocación, la demora o la adversidad sin tomar represalias ni perder la esperanza. Se aplica a la paciencia humana hacia otros (Mt 18:26, 29), al carácter esencial del amor (1 Co 13:4), a los creyentes que aguardan el retorno del Señor (1 Ts 5:14; Stg 5:7-8), a la perseverancia de Abraham para alcanzar la promesa (He 6:15) y a la paciencia de Dios mismo que no quiere que nadie perezca (2 P 3:9).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71889, 'spa', 'Paciencia, longanimidad — la cualidad de refrenar la ira y soportar la provocaci', 'Paciencia, longanimidad — la cualidad de refrenar la ira y soportar la provocación o la adversidad sin represalias. Aplicada a la tolerancia de Dios al demorar el juicio (Ro 2:4; 9:22; 1 Ti 1:16; 2 P 3:15), al fruto del Espíritu en los creyentes (Gá 5:22) y a la virtud práctica exigida en la vida comunitaria (Ef 4:2; Col 1:11; 3:12; 2 Ti 3:10; 4:2). La etimología — μακρός («largo») más θυμός («pasión») — evoca un temperamento pausado que soporta sin estallar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71892, 'spa', 'Pacientemente, con longanimidad', 'La forma adverbial modifica el verbo ''escuchar,'' solicitando una manera de atender caracterizada por la paciencia y la tolerancia. La evidencia interlingüística (español ''pacientemente,'' francés ''patiemment'') confirma el núcleo semántico de resistencia paciente, cualidad esencial para comprender asuntos teológicos y culturales complejos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71893, 'spa', 'Largo, prolongado', 'Largo en extensión o duración: describe algo física o temporalmente extendido, dilatado o prolongado. Las tres apariciones involucran las ''largas oraciones'' de los escribas y fariseos (Matt 23:14; Mark 12:40; Luke 20:47), donde Jesús critica la religiosidad ostentosa. El español ''largamente'' enfatiza el estiramiento temporal: oraciones prolongadas como muestra de piedad más que como expresión genuina de devoción.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71894, 'spa', 'Lejano, distante', 'Lejano o distante en el espacio: describe lejanía geográfica más que extensión lineal. El hijo pródigo viaja a un ''país lejano'' (Luke 15:13), el noble parte a una ''tierra distante'' (Luke 19:12), y Pedro promete el Espíritu Santo a quienes están ''lejos'' (Acts 2:39). El español ''lejano'' distingue claramente esta lejanía espacial del sentido temporal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71896, 'spa', 'Longevo, de larga vida', 'La forma nominativa masculina singular funciona predicativamente: ''para que seas longevo''. Las glosas multilingües (español ''de-larga-vida'', alemán ''langlebig'') captan el sentido literal del compuesto referido a la duración temporal extendida aplicada a la vida humana, una bendición tangible ligada a la fidelidad al pacto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71897, 'spa', 'Enfermedad corporal', 'Enfermedad, dolencia o padecimiento físico. Las tres apariciones en Mateo describen el ministerio sanador de Jesús: recorría Galilea «sanando toda enfermedad y toda dolencia en el pueblo» (4:23, repetido casi textualmente en 9:35), y concedió a los doce discípulos autoridad «para sanar toda enfermedad y toda dolencia» (10:1). La repetición subraya la naturaleza integral de su poder sanador.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71898, 'spa', 'Suave, lujoso o indulgente', 'Suave o fino en textura, y por extensión lujoso, afeminado o moralmente indulgente. En Mateo 11:8 (dos veces) y Lucas 7:25, Jesús pregunta si la gente fue al desierto a ver a alguien con ropas suaves y finas — lo opuesto al manto de pelo de camello de Juan — señalando el lujo cortesano. En 1 Corintios 6:9 el término aparece en una lista de vicios con sentido moral: la blandura como debilidad autocomplaciente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71899, 'spa', 'Patriarca antediluviano', 'La forma genitiva incorpora a este patriarca primitivo en la cadena genealógica. La transliteración consistente entre idiomas (español ''Maleleḗl'', francés ''Maléléel'') mantiene la forma septuagintal del nombre hebreo, preservando la dignidad arcaica de estos ancestros primordiales.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71900, 'spa', 'Especialmente, sobre todo — adverbio superlativo usado para destacar un elemento', 'Especialmente, sobre todo — adverbio superlativo usado para destacar un elemento de un grupo más amplio, dándole énfasis superior, traducible como «especialmente», «sobre todo» o «ante todo». Aparece frecuentemente en la exhortación e instrucción paulina para aguzar un principio general hacia una aplicación específica (Gá 6:10, hacer el bien «especialmente» a los hermanos en la fe; 2 Ti 4:13, traer los libros, «sobre todo» los pergaminos; 1 Ti 5:17, «mayormente» los que trabajan en la palabra).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71901, 'spa', 'más, más bien', 'Adverbio comparativo que significa ''más'' (en grado) o ''más bien'' (en preferencia), forma comparativa de μάλα. Destaca en los argumentos qal wahomer de Jesús: «¿cuánto más vuestro Padre dará cosas buenas?» (Mt 7:11; cf. 6:26, 30). Pablo lo emplea para intensificación enfática --πολλῷ μᾶλλον, ''mucho más'' (Fil 2:12; Ro 5:9)-- y para expresar preferencia correctiva, ''más bien'' (Ef 4:28; 5:11).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71903, 'spa', 'Siervo del sumo sacerdote', 'La forma nominativa identifica al individuo que experimentó tanto la violencia de Pedro como la misericordia sanadora de Jesús. La preservación de este nombre a través de las traducciones marca el momento histórico específico en que Jesús reprendió la resistencia violenta y demostró que su reino opera bajo principios distintos al poder terrenal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71904, 'spa', 'Abuela', 'El dativo singular indica a la abuela como alguien en quien habitaba la fe. Las traducciones interlingüísticas (español ''abuela'', alemán ''Grossmutter'') identifican este como el término de parentesco estándar para la madre de uno de los padres, enfatizando el papel de las abuelas en transmitir la fe religiosa mediante la instrucción familiar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71905, 'spa', 'Riqueza personificada', 'Riqueza o posesiones materiales personificadas como una deidad rival o un amo. Jesús declara que nadie puede servir a Dios y a Mamón (Mateo 6:24; Lucas 16:13), enmarcando la búsqueda de riquezas como una forma de idolatría. En Lucas 16:9, 11 habla del «mamón injusto» y de ser «fiel en el mamón», tratando la riqueza como campo de prueba para la fidelidad espiritual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71906, 'spa', 'Profeta cristiano en Antioquía', 'La forma nominativa identifica a este individuo como líder en la iglesia antioquena. Su trasfondo único — criado en la corte de Herodes pero ahora sirviendo como profeta cristiano — ilustra las transformaciones sociales radicales que produjo el evangelio, reuniendo en una sola comunidad a personas de orígenes vastamente diferentes.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71907, 'spa', 'Manasés', 'Manasés, nombre personal hebreo portado por dos figuras. Mateo 1:10 (listado dos veces consecutivas) incluye al rey Manasés de Judá en la genealogía de Jesús, uno de los reyes más perversos de Judá que posteriormente se arrepintió. Apocalipsis 7:6 se refiere a «la tribu de Manasés» entre las doce tribus cuyos siervos son sellados, remontándose al hijo primogénito de José.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71908, 'spa', 'Adquirir conocimiento, habilidad o comprension a traves del estudio, la instrucc', 'Adquirir conocimiento, habilidad o comprension a traves del estudio, la instruccion o la experiencia vivida. El espanol ''aprender'' y el frances ''apprendre'' rinden uniformemente el sentido de aprendizaje. Jesus dice ''aprendan de mi'' (Mt. 11:29) y ''vayan y aprendan lo que significa esto'' (Mt. 9:13). La parabola de la higuera ensena a los discipulos a ''aprender'' de la observacion (Mt. 24:32; Mr. 13:28). Juan 6:45 cita a Isaias: ''todo el que oyo y aprendio del Padre.''');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71914, 'spa', 'Averiguar, descubrir o llegar a conocer un hecho especifico mediante indagacion ', 'Averiguar, descubrir o llegar a conocer un hecho especifico mediante indagacion o informe, en lugar de un estudio prolongado. El espanol cambia a ''habiendo sabido'' (habiendo descubierto), distinto del verbo de aprendizaje ''aprender''. Este sentido aparece en Hechos 23:27, donde el tribuno Claudio Lisias ''supo'' que Pablo era ciudadano romano — un momento puntual de descubrimiento factico, no un proceso de instruccion.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71922, 'spa', 'Locura o demencia', 'El acusativo singular funciona como objeto: ''la locura te domina.'' Las traducciones multilingües (español ''locura'', francés ''folie'') transmiten el rango semántico desde la insania clínica hasta el entusiasmo irracional. La acusación de Festo revela la ofensa del evangelio a la sabiduría mundana: lo que parece necedad para los que se pierden es poder de Dios para los que se salvan.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71923, 'spa', 'Maná, sustento divino', 'El alimento milagroso que Dios proveyó diariamente a Israel en el desierto, usado tipológicamente en el NT para el sustento divino y escatológico. En Juan 6:31, 49 Jesús contrasta el maná perecedero del desierto consigo mismo como el pan vivo del cielo. Hebreos 9:4 menciona la urna de maná preservada en el arca, memorial tangible de la fidelidad de Dios. Apocalipsis 2:17 promete «maná escondido» a los vencedores.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71924, 'spa', 'Adivinación ocultista', 'El participio presente medio/pasivo ''adivinando'' modifica la manera en que ella generaba ganancias para sus amos. Las traducciones multilingües (español ''adivinando'', francés ''pratiquer-la-magie'') identifican esto como adivinación ocultista, lo opuesto a la revelación profética auténtica, mostrando que el conocimiento sobrenatural puede provenir de fuentes espirituales ilegítimas que deben ser renunciadas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71925, 'spa', 'Marchitarse o desvanecerse', 'El futuro pasivo ''se marchitará'' describe el inevitable deterioro de las empresas del rico. Las traducciones multilingües (español ''se-marchitará'', alemán ''verwelken'') enfatizan la imaginería botánica de marchitarse bajo el calor, una metáfora poderosa sobre la naturaleza efímera de la prosperidad terrenal alejada de los valores eternos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71927, 'spa', 'Perla', 'Gema preciosa formada dentro de la concha de un molusco, valorada como mercancía costosa y adorno suntuoso. El NT la emplea literalmente (1 Ti 2:9 advierte contra el uso ostentoso de perlas; Apocalipsis cataloga perlas entre las riquezas de Babilonia) y figuradamente para el valor supremo del reino de Dios (Mt 13:45-46, la perla de gran precio).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71932, 'spa', 'Nombre propio de una mujer de Betania, hermana de María y Lázaro, derivado del a', 'Nombre propio de una mujer de Betania, hermana de María y Lázaro, derivado del arameo marta (''señora, ama''). Aparece en dos escenas fundamentales: sirviendo a Jesús mientras María escucha a sus pies (Lucas 10:38-42), y saliendo al encuentro de Jesús junto a la tumba de Lázaro, donde hace una notable confesión de fe (Juan 11:20-27). Las traducciones en todas las lenguas transliteran uniformemente el nombre.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71933, 'spa', 'María / Mariam', 'El nombre María/Mariam, compartido por varias mujeres del Nuevo Testamento. La principal es María la madre de Jesús (Mt 1:16; Lc 1:27; Hch 1:14), seguida de María Magdalena (Mr 16:1; Jn 20:1-18), María de Betania (Lc 10:39) y María mujer de Cleofas (Jn 19:25). Las dos formas griegas no conllevan distinción semántica alguna.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71936, 'spa', 'Marcos (nombre propio)', 'Nombre propio de Marcos (griego Μάρκος, del latín Marcus), referido a Juan Marcos, primo de Bernabé y compañero de los apóstoles. Sus apariciones trazan un arco desde el trabajo misionero con Pablo y Bernabé (Hch 12:12, 25; 15:37, 39), la reconciliación con Pablo (Col 4:10; 2 Ti 4:11; Flm 24), hasta su cercanía con Pedro (1 P 5:13).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71937, 'spa', 'Mármol como material', 'La forma genitiva ''de mármol'' especifica la composición material dentro de un inventario comercial. La transliteración consistente entre idiomas (''mármol'', ''Marmor'') identifica esta piedra como material de construcción lujoso, símbolo de las ambiciones arquitectónicas de la Roma imperial y de la cultura material que a la postre resultaría tan efímera como la gloria de Babilonia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71938, 'spa', 'testificar, dar testimonio', 'Testificar activamente, dar testimonio o declarar lo que se ha visto, conocido o creído como verdadero. Juan el Bautista es el paradigma: vino «para dar testimonio de la luz» (Jn 1:7-8), y el verbo aparece reiteradamente cuando Jesús, el Espíritu y la Escritura misma testifican (Jn 5:39; 15:26). Abarca desde lo forense hasta la proclamación kerigmática.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71945, 'spa', 'ser atestiguado, recibir testimonio', 'Voz pasiva: ser atestiguado, acreditado o bien considerado; el sujeto recibe testimonio en vez de darlo. En Hch 6:3, los diáconos deben ser «de buen testimonio»; en Hch 16:2, Timoteo «gozaba de buen testimonio de los hermanos»; en He 11:2, los antiguos «alcanzaron buen testimonio» por su fe. El enfoque se desplaza del testigo al testimoniado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71973, 'spa', 'El acto o contenido de dar testimonio, abarcando el testimonio legal, la atestig', 'El acto o contenido de dar testimonio, abarcando el testimonio legal, la atestiguacion profetica y el testimonio cristologico. En el Evangelio de Juan porta un peso cuasi-forense mientras se adjudican afirmaciones en pugna: el testimonio del Bautista sobre Jesus (Jn 1:7, 19; 5:33-36), el autotestimonio de Jesus cuestionado por los fariseos (Jn 8:13-14) y el testimonio del Padre confirmado por las obras (Jn 5:36-37). En los relatos del juicio ante el Sanedrin toma un giro forensico al buscar testimonio contra Jesus (Mr 14:55-59). Apocalipsis lo eleva a proporciones cosmicas: el testimonio de Jesus se convierte en fundamento de la persecucion y la perseverancia de los santos (Ap 1:2, 9; 12:11, 17; 19:10).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71975, 'spa', 'Testimonio, testificación, prueba', 'Testimonio, testificación, prueba: Testimonio o testificación — una declaración, acto o evidencia que atestigua la verdad. Usado tanto del evangelio proclamado a las naciones como evidencia pública (Mt 24:14) como de acciones realizadas «para testimonio a ellos» (Mt 8:4; Mr 1:44; Mr 6:11). También lleva el eco veterotestamentario del «tabernáculo del testimonio» (Hch 7:44), refiriéndose a las tablas del pacto. El español «testimonio» conserva tanto los matices forenses como declarativos del término griego.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71976, 'spa', 'Testificar solemnemente', 'Dar testimonio solemne o afirmar con gravedad, invocando a Dios o a otros como testigos de la veracidad de lo declarado. Pablo lo emplea en momentos decisivos: al declararse inocente de toda sangre (Hch 20:26), al advertir sobre la obligación de la circuncisión (Gá 5:3) y al exhortar a andar dignos de Dios (1 Ts 2:12).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71977, 'spa', 'Persona que da testimonio de la verdad, ya sea en un proceso judicial, como test', 'Persona que da testimonio de la verdad, ya sea en un proceso judicial, como testigo ocular de eventos, o mediante la proclamacion fiel incluso hasta la muerte. El sentido legal clasico rige los relatos del juicio en los Evangelios (Mt 26:65; Mr 14:63) y la regla deuteronomica de los dos testigos (Mt 18:16; 2 Co 13:1). El sentido apostolico-kerigmatico domina Hechos, donde los Doce son ''testigos de su resurreccion'' (Hch 1:8, 22; 2:32; 3:15; 10:39, 41). Hebreos introduce la celebre ''nube de testigos'' (12:1) que atestiguan la fe con la forma de sus vidas. Apocalipsis completa la trayectoria: Antipas es ''mi testigo fiel'' que fue muerto (Ap 2:13), y los ''dos testigos'' profetizan y mueren (Ap 11:3), pasajes que dieron al espanol la palabra ''martir''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71980, 'spa', 'Morder o roer', 'El imperfecto medio/pasivo en tercera persona del plural ''mordían'' describe una acción continua durante la plaga. La evidencia interlingüística (español ''mordían'', francés ''mâcher'') confirma la visceral fisicalidad de esta respuesta al juicio, una reacción involuntaria al sufrimiento que paradójicamente coexiste con la persistencia voluntaria en la rebelión contra Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71981, 'spa', 'Azotar, flagelar', 'Golpear o flagelar a alguien con un látigo o azote, infligiendo castigo físico. La palabra implica un instrumento de castigo, no golpes a mano. En las predicciones sinópticas de la pasión (Mt 20:19; Mc 10:34; Lc 18:33), μαστιγόω anticipa la flagelación romana de Jesús. En Mt 10:17 y 23:34 describe la flagelación sinagogal de misioneros cristianos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71987, 'spa', 'Azotar, flagelar', 'El infinitivo presente «azotar» expresa una acción contemplada: «¿Os es lícito azotar...?» Las traducciones interlingüísticas (español «azotar», francés «battre») identifican esto como castigo corporal mediante instrumentos de golpe, una práctica que la ciudadanía de Pablo prohibía legalmente, generando una crisis cuando las autoridades descubrieron que habían atado ilegalmente a un ciudadano romano.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71988, 'spa', 'Aflicción, enfermedad', 'Aflicción o enfermedad entendida figuradamente como un ''azote'': sufrimiento concebido como un golpe que hiere. La mujer con hemorragia es sanada ''de su azote'' (Mark 5:29, 34), y los enfermos se agolpan hacia Jesús porque sana todos sus ''azotes'' (Mark 3:10; Luke 7:21). El español ''enfermedad'' junto a ''azotes'' revela la doble naturaleza de la metáfora.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71989, 'spa', 'Látigo, flagelo', 'Látigo o flagelo como instrumento literal de castigo físico: correas de cuero o varas usadas en la flagelación judicial romana. En Acts 22:24 el tribuno ordena que Pablo sea ''examinado con azotes'' (μάστιξιν), procedimiento estándar para extraer testimonio de no ciudadanos. En Heb 11:36 los fieles soportaron ''azotes'' entre otras torturas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71993, 'spa', 'Pecho o seno', 'El pecho o seno. Lucas 11:27 recoge la bendición de una mujer al «vientre que te llevó y los pechos que te amamantaron», ensalzando a la madre de Jesús por su lactancia. Lucas 23:29 cita la profecía de Jesús: «Bienaventurados los pechos que nunca amamantaron», una bendición paradójica que señala una catástrofe tan grave que la infecundidad parecerá afortunada. Apocalipsis 1:13 describe al Hijo del Hombre ceñido con un cinturón de oro alrededor del pecho.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71994, 'spa', 'Palabrería vana', 'El acusativo singular funciona como el objeto hacia el cual se desvían: «se apartaron a la palabrería vana». La evidencia interlingüística (español «palabrería vana», alemán «leeres Geschwätz») subraya la naturaleza vacua e improductiva de una discusión divorciada del amor y la verdad, advirtiendo contra ejercicios intelectuales que generan más ruido que luz.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71995, 'spa', 'Hablador de vanidades', 'El nominativo masculino plural «habladores de vanidades» identifica una clase de falsos maestros. Las traducciones interlingüísticas (español «vana palabrería», alemán «Schwätzer») caracterizan a estos individuos como verbosos pero vacuos, cuyas muchas palabras contienen poca verdad y mucho engaño, requiriendo una refutación firme para proteger a los creyentes de su influencia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71996, 'spa', 'Inútil, sin valor', 'Inútil, fútil: describe cosas, acciones o estados que carecen de valor real o resultado productivo. Pablo advierte que si Cristo no ha resucitado, la fe de los corintios es μάταιος — fútil, sin lograr nada (1 Cor 15:17). Titus 3:9 y Jas 1:26 califican ciertas conductas como vacías de provecho. El español ''vana'' refuerza este significado de infructuosidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71997, 'spa', 'Cosas vanas', 'Vano, vacío (referido a cosas idolátricas o ilusorias): caracteriza categorías enteras de objetos o prácticas como desprovistas de realidad divina. En Acts 14:15, Pablo insta a apartarse de ''cosas vanas'' (ματαίων), ídolos sin vida, hacia el Dios viviente. El español ''vanas cosas'' capta este uso sustantivado que apunta a un sistema de adoración sin valor.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (71998, 'spa', 'Fútil, vacuo', 'Fútil, intelectualmente vacío: aplicado al razonamiento o pensamiento humano que resulta hueco ante Dios. En 1 Cor 3:20 Pablo cita el Psalm 94:11: ''El Señor conoce los pensamientos de los sabios, que son vanos (μάταιοι).'' Aquí la palabra expone la bancarrota de la sabiduría humana apartada de la revelación divina. El español ''vanos'' preserva este matiz de futilidad intelectual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72001, 'spa', 'Vanidad o futilidad', 'Vanidad, futilidad o vacuidad: la cualidad de carecer de propósito. Romanos 8:20 afirma que la creación «fue sometida a vanidad» por la caída, frustrada en alcanzar su fin original. Efesios 4:17 advierte a los creyentes que no caminen «en la vanidad de su mente» como los gentiles, cuyo pensamiento oscurecido por el pecado genera un razonamiento vacío. 2 Pedro 2:18 describe a falsos maestros profiriendo «palabras infladas y vanas».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72002, 'spa', 'Volverse vano, envanecerse', 'El aoristo pasivo en tercera persona del plural «se envanecieron» describe el resultado de negarse a reconocer a Dios. La evidencia interlingüística (español «se hicieron vanos», alemán «nichtig werden») transmite la transformación de la sabiduría potencial en necedad efectiva, mostrando que la autonomía respecto a Dios no produce liberación sino el vaciamiento del pensamiento humano en la vanidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72004, 'spa', 'Mateo el apóstol', 'Nombre propio que designa a uno de los doce apóstoles de Jesús. Llamado directamente desde su puesto de recaudación de impuestos (Mt 9:9), ejemplifica un discipulado radical. El nombre probablemente deriva del hebreo mattanyah (''don de YHWH''). Aparece entre los Doce en todo catálogo sinóptico y en Hechos 1:13, y se lo empareja consistentemente con Tomás.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72008, 'spa', 'Nombre propio genealógico', 'La forma genitiva sitúa a este individuo dentro de la cadena ancestral. La preservación multilingüe de la transliteración griega refleja la práctica genealógica habitual de mantener los nombres históricos en sus formas recibidas, contribuyendo a documentar la descendencia de Jesús desde David a través de una línea no real.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72010, 'spa', 'La espada como arma física', 'La espada como arma física: la espada corta, daga o cuchilla portada por soldados, guardias o individuos. Es la μάχαιρα que Pedro desenvaina en Getsemaní (Mt 26:51), el arma con que Herodes ejecuta a Jacobo (Hch 12:2) y el instrumento de martirio enumerado entre las pruebas de fe (Ro 8:35, Heb 11:37). La advertencia de Jesús «todos los que tomen espada, a espada perecerán» (Mt 26:52) subraya la violencia inherente al arma.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72011, 'spa', 'Espadas en plural, referidas a grupos armados, fuerza militar o la amenaza colec', 'Espadas en plural, referidas a grupos armados, fuerza militar o la amenaza colectiva de violencia. La multitud que arresta a Jesús viene «con espadas y palos» (Mt 26:47, Mr 14:43), y Jesús los reprende: «¿Han salido con espadas y palos para prenderme?» (Mt 26:55). Cuando los discípulos dicen «Señor, aquí hay dos espadas» (Lc 22:38), el plural señala disposición para el conflicto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72012, 'spa', 'La espada como instrumento de poder judicial o divinamente autorizado, empuñada ', 'La espada como instrumento de poder judicial o divinamente autorizado, empuñada por las autoridades gobernantes o por Dios mismo. Pablo declara que el gobernante «no en vano lleva la espada» (Ro 13:4), señalando la autoridad otorgada por Dios al Estado para ejecutar justicia. Este sentido judicial conecta el arma literal con sus extensiones metafóricas, mostrando la espada como símbolo de poder letal autorizado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72013, 'spa', 'Contiendas y disputas', 'Querellas, disputas y conflictos entre personas, ya sea contienda verbal o discordia interpersonal más amplia. En Santiago 4:1 aparece junto a ''guerras'' (πόλεμοι) para describir las amargas rivalidades que brotan de deseos egoístas. Pablo lo usa tanto para conflictos externos (2 Co 7:5) como para las disputas inútiles que surgen de controversias necias (2 Ti 2:23, Tit 3:9).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72014, 'spa', 'Pelear o disputar', 'Reñir, disputar o pelear, ya sea física o verbalmente. En Hechos 7:26 describe un altercado físico entre dos hebreos, mientras que en Juan 6:52 capta la acalorada discusión entre los oyentes judíos. Pablo prohíbe al siervo del Señor ser contencioso (2 Ti 2:24), y Santiago 4:2 vincula el pelear con deseos insatisfechos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72015, 'spa', 'Jactarse grandemente', 'El presente indicativo en tercera persona del singular describe la acción característica de la lengua. Las traducciones interlingüísticas (español ''se-jacta,'' alemán ''sich-ruehmen'') captan la naturaleza autoengrandecedora del habla que hace afirmaciones excesivas, resaltando el peligro que Santiago ve en la capacidad de la lengua humana para la expresión orgullosa y destructiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72016, 'spa', 'Obras grandiosas', 'El acusativo neutro plural funciona como objeto de lo que se proclama. Las traducciones interlingüísticas (español ''grandezas,'' francés ''magnifique'') subrayan la naturaleza extraordinaria de los actos de Dios que merecen ser proclamados, el contenido mismo del testimonio capacitado por el Espíritu que trasciende las barreras lingüísticas y culturales para declarar la gloria divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (72017, 'spa', 'Majestad divina', 'Majestad, magnificencia o grandeza. Lucas 9:43 describe a los presentes «asombrados de la majestad de Dios» manifestada cuando Jesús sanó al endemoniado: grandeza divina hecha visible. Hechos 19:27 recoge la advertencia de Demetrio de que la «majestad» de Artemisa será destruida si el pueblo escucha a Pablo. 2 Pedro 1:16 contrasta los mitos con el testimonio ocular: «fuimos testigos oculares de su majestad» en la Transfiguración.');